			dw kw_strcmpeq, var_chks_got, var_chks_want
			dw kw_goto_iffalse_n, if9_1

			; 183: Print "ok ";
			dw kw_printzoscii
			dw glyph_6F, glyph_6B, glyph_20, 0		; "ok "

			; 184: Else
			dw if9_e_go
if9_1:

			; 185: Print "FAIL["; got; "] ";
			dw kw_printzoscii
			dw glyph_46, glyph_41, glyph_49, glyph_4C, glyph_5B, 0		; "FAIL["
			dw kw_printstrvar, var_chks_got
			dw kw_printzoscii
			dw glyph_5D, glyph_20, 0		; "] "

			; 186: bad = bad + 1
			dw kw_inc, var_bad

			; 187: End If
if9_e:
			dw p_chks_r

; ============================================================
; function twice (normal mode)
; ============================================================

p_twice:

			; 191: Twice = v + v
			dw kw_l_add, var_twice_v, var_twice_v, var_twice_twice
			dw p_twice_r

; ============================================================
; sub addto (normal mode)
; ============================================================

p_addto:

			; 195: x = x + y
			dw kw_l_add, var_addto_x, var_addto_y, var_addto_x
			dw p_addto_r

; ============================================================
; function fact (normal mode)
; ============================================================

p_fact:

			; 199: Dim r As Long

			; 200: r = 1
			dw kw_l_mov, llit_1, var_fact_r

			; 201: Do While k > 1
do10_t:
			dw kw_scpgtvl, var_fact_k, 1
			dw kw_goto_iffalse_n, do10_e

			; 202: r = r * k
			dw kw_l_itol, var_fact_k, ltmp1
			dw kw_l_mul, var_fact_r, ltmp1, var_fact_r

			; 203: k = k - 1
			dw kw_dec, var_fact_k

			; 204: Loop
			dw do10_t_go
do10_e:

			; 205: Fact = r
			dw kw_l_mov, var_fact_r, var_fact_fact
			dw p_fact_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if1_e_go:			ld sp, if1_e
			jp ntc_xn
if2_e_go:			ld sp, if2_e
