			ldir
			ld (p_addto_rs), sp
			ld sp, p_addto
			jp ntc_xn
p_addto_r:		; end of addto
			ld de, (p_addto_a0)
			ld hl, var_addto_x
			ld bc, 4
			ldir
			ld sp, (p_addto_rs)
			jp ntc_xn
p_fact_c:		; call fact (normal)
			pop hl			; k
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_fact_k), de
			ld hl, 0
