; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_ticks @data
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_aptr @data
ntc_aptr:		dw 0			; atoi: text pointer

;## ntc_d_hook @data
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_iftrue (normal mode copy)
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue_n:
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			pop hl
			jr z, ntc_ftov_t
			ld (hl), 0
			inc hl
			ld (hl), 0
			ret
ntc_ftov_t:
			ld (hl), #ff
			inc hl
			ld (hl), #ff
			ret

; ============================================================
; Arithmetic
; ============================================================

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_dec
;kw_dec, <var>
kw_dec:
			pop hl
			ld a, (hl)
			dec (hl)
			or a
			ret nz
			inc hl
			dec (hl)
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sgt

;## kw_cpeqvv ntc_cmp
;kw_cpeqvv, <var1>, <var2>
kw_cpeqvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_eq

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printzoscii ntc_data ntc_font ntc_plat_screen
;kw_printzoscii / dw glyph, glyph, ..., 0  - ZOSCII text inline in the thread
;  each word points at an 8 byte glyph bitmap. 1 = newline, 0 = end (only those two:
;  a program at #0040 can have glyphs below #0100)
kw_printzoscii:
			pop de
			ld a, d
			or a
			jr nz, ntc_pz_glyph
			ld a, e
			cp 2
			jr c, ntc_pz_ctl
ntc_pz_glyph:
			ld ix, kw_printzoscii
			jp ntc_plat_putglyph
ntc_pz_ctl:
			or a
			ret z
			ld ix, kw_printzoscii
			jp ntc_plat_newline

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_scrinit ntc_data ntc_plat_screen
;kw_scrinit  - first word of any program that prints or reads keys:
;  mode 1, ROMs off, clear screen
kw_scrinit:
			ld a, 1
			ld ix, ntc_next
			jp ntc_plat_mode

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_itol
;kw_l_itol, <intvar>, <dest>  - Integer to Long (sign extended)
kw_l_itol:
			pop hl
			pop de
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			ld (de), a
			inc de
			rla
			sbc a, a
			ld (de), a
			inc de
			ld (de), a
			ret

;## kw_l_ltoi
;kw_l_ltoi, <long>, <intdest>  - Long to Integer (low 16 bits)
kw_l_ltoi:
			pop hl
			pop de
			ldi
			ldi
			ret

;## kw_l_add
;kw_l_add, <a>, <b>, <dest>  - a + b
kw_l_add:
			pop hl
			pop de
			pop ix
			ld a, (de)
			add a, (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+3), a
			ret

;## kw_l_sub
;kw_l_sub, <a>, <b>, <dest>  - a - b
kw_l_sub:
			pop de
			pop hl
			pop ix
			ld a, (de)
			sub (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+3), a
			ret

;## kw_l_and
;kw_l_and, <a>, <b>, <dest>
kw_l_and:
			pop hl
			pop de
			pop ix
			ld a, (de)
			and (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			and (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			and (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			and (hl)
			ld (ix+3), a
			ret

;## kw_l_or
;kw_l_or, <a>, <b>, <dest>
kw_l_or:
			pop hl
			pop de
			pop ix
			ld a, (de)
			or (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			or (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			or (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			or (hl)
			ld (ix+3), a
			ret

;## kw_l_xor
;kw_l_xor, <a>, <b>, <dest>
kw_l_xor:
			pop hl
			pop de
			pop ix
			ld a, (de)
			xor (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			xor (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			xor (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			xor (hl)
			ld (ix+3), a
			ret

;## kw_l_not
;kw_l_not, <a>, <dest>
kw_l_not:
			pop hl
			pop de
			ld a, (hl)
			cpl
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			cpl
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			cpl
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			cpl
			ld (de), a
			ret

;## kw_l_neg
;kw_l_neg, <a>, <dest>  - 0 - a
kw_l_neg:
			pop hl
			pop ix
			xor a
			sub (hl)
			ld (ix+0), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (ix+1), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (ix+2), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (ix+3), a
			ret

;## kw_l_abs kw_l_mov kw_l_neg
;kw_l_abs, <a>, <dest>
kw_l_abs:
			pop hl
			inc hl
			inc hl
			inc hl
			bit 7, (hl)
			dec hl
			dec hl
			dec hl
			jr z, ntc_labs_pos
			pop ix
			xor a
			sub (hl)
			ld (ix+0), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (ix+1), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (ix+2), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (ix+3), a
			ret
ntc_labs_pos:
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_sgn
;kw_l_sgn, <a>, <intdest>  - -1, 0 or 1
kw_l_sgn:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ld de, 0
			jr z, ntc_lsg_st
			inc de
			bit 7, (hl)
			jr z, ntc_lsg_st
			ld de, -1
ntc_lsg_st:
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_lcmp ntc_ldata
; DE = a, HL = b: work out a - b. ntc_lsgn = #80 if a < b (signed),
; ntc_lcnt = 0 if a = b. jp (ix) back.
ntc_lcmp:
			ld a, (de)
			sub (hl)
			ld (ntc_lr), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+3), a
			ld b, 0
			jp po, ntc_lcm_nov
			ld b, #80
ntc_lcm_nov:
			xor b
			and #80
			ld (ntc_lsgn), a
			ld hl, ntc_lr
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ld (ntc_lcnt), a
			jp (ix)

;## kw_l_cplt ntc_lcmp
;kw_l_cplt, <a>, <b>  - Z if a < b
kw_l_cplt:
			pop de
			pop hl
			ld ix, ntc_lclt
			jp ntc_lcmp
ntc_lclt:
			ld a, (ntc_lsgn)
			xor #80
			ret

;## kw_l_cpge ntc_lcmp
;kw_l_cpge, <a>, <b>  - Z if a >= b
kw_l_cpge:
			pop de
			pop hl
			ld ix, ntc_lcge
			jp ntc_lcmp
ntc_lcge:
			ld a, (ntc_lsgn)
			or a
			ret

;## kw_l_cpeq ntc_lcmp
;kw_l_cpeq, <a>, <b>  - Z if a = b
kw_l_cpeq:
			pop de
			pop hl
			ld ix, ntc_lceq
			jp ntc_lcmp
ntc_lceq:
			ld a, (ntc_lcnt)
			or a
			ret

;## kw_l_cpne ntc_lcmp
;kw_l_cpne, <a>, <b>  - Z if a <> b
kw_l_cpne:
			pop de
			pop hl
			ld ix, ntc_lcne
			jp ntc_lcmp
ntc_lcne:
			ld a, (ntc_lcnt)
			or a
			jr z, ntc_lcne_f
			xor a
			ret
ntc_lcne_f:
			or 1
			ret

;## kw_l_cple ntc_lcmp
;kw_l_cple, <a>, <b>  - Z if a <= b
kw_l_cple:
			pop de
			pop hl
			ld ix, ntc_lcle
			jp ntc_lcmp
ntc_lcle:
			ld a, (ntc_lcnt)
			or a
			ret z
			ld a, (ntc_lsgn)
			xor #80
			ret

;## kw_l_cpgt ntc_lcmp
;kw_l_cpgt, <a>, <b>  - Z if a > b
kw_l_cpgt:
			pop de
			pop hl
			ld ix, ntc_lcgt
			jp ntc_lcmp
ntc_lcgt:
			ld a, (ntc_lcnt)
			or a
			jr z, ntc_lcgt_f
			ld a, (ntc_lsgn)
			or a
			ret
ntc_lcgt_f:
			or 1
			ret

;## ntc_lmul ntc_ldata
; ntc_la * ntc_lb -> ntc_lr (low 32 bits, same signed / unsigned). jp (ix)
ntc_lmul:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_lm_loop:
			ld hl, ntc_lb+3
			srl (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			jr nc, ntc_lm_skip
			ld de, ntc_la
			ld hl, ntc_lr
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
ntc_lm_skip:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			djnz ntc_lm_loop
			jp (ix)

;## ntc_lnegm
; HL = address of a Long: negate it in place. jp (ix)
ntc_lnegm:
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			jp (ix)

;## ntc_ldiv ntc_ldata ntc_lnegm
; ntc_la / ntc_lb signed, truncating: quotient in ntc_la, remainder (with
; the dividend's sign) in ntc_lr. Divide by 0: quotient 0, remainder =
; dividend. jp (ix) back.
ntc_ldiv:
			ld (ntc_lix), ix
			ld hl, (ntc_lb)
			ld a, h
			or l
			ld hl, (ntc_lb+2)
			or h
			or l
			jr nz, ntc_ld_nz
			ld hl, (ntc_la)
			ld (ntc_lr), hl
			ld hl, (ntc_la+2)
			ld (ntc_lr+2), hl
			ld hl, 0
			ld (ntc_la), hl
			ld (ntc_la+2), hl
			jp ntc_ld_out
ntc_ld_nz:
			ld a, (ntc_la+3)
			ld (ntc_lsgn), a
			ld b, a
			ld a, (ntc_lb+3)
			xor b
			ld (ntc_lcnt), a
			ld a, (ntc_la+3)
			or a
			jp p, ntc_ld_apos
			ld hl, ntc_la
			ld ix, ntc_ld_apos
			jp ntc_lnegm
ntc_ld_apos:
			ld a, (ntc_lb+3)
			or a
			jp p, ntc_ld_bpos
			ld hl, ntc_lb
			ld ix, ntc_ld_bpos
			jp ntc_lnegm
ntc_ld_bpos:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_ld_loop:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld hl, ntc_lr
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld de, ntc_lr
			ld hl, ntc_lb
			ld a, (de)
			sub (hl)
			ld (ntc_lt), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+3), a
			jr c, ntc_ld_no
			ld hl, (ntc_lt)
			ld (ntc_lr), hl
			ld hl, (ntc_lt+2)
			ld (ntc_lr+2), hl
			ld hl, ntc_la
			set 0, (hl)
ntc_ld_no:
			djnz ntc_ld_loop
			ld a, (ntc_lcnt)
			or a
			jp p, ntc_ld_qpos
			ld hl, ntc_la
			ld ix, ntc_ld_qpos
			jp ntc_lnegm
ntc_ld_qpos:
			ld a, (ntc_lsgn)
			or a
			jp p, ntc_ld_out
			ld hl, ntc_lr
			ld ix, ntc_ld_out
			jp ntc_lnegm
ntc_ld_out:
			ld ix, (ntc_lix)
			jp (ix)

;## kw_l_mul ntc_lmul ntc_ldata
;kw_l_mul, <a>, <b>, <dest>  - a * b
kw_l_mul:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			ld ix, ntc_lmu_back
			jp ntc_lmul
ntc_lmu_back:
			ld hl, ntc_lr
; copy the 4 bytes at HL to (ntc_ldst), then next keyword
ntc_lstore:
			ld de, (ntc_ldst)
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_div ntc_ldiv kw_l_mul
;kw_l_div, <a>, <b>, <dest>  - a \ b
kw_l_div:
			ld ix, ntc_ldv_back
ntc_ldv_go:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			jp ntc_ldiv
ntc_ldv_back:
			ld hl, ntc_la
			jp ntc_lstore

;## kw_l_mod kw_l_div
;kw_l_mod, <a>, <b>, <dest>  - a Mod b
kw_l_mod:
			ld ix, ntc_lmd_back
			jp ntc_ldv_go
ntc_lmd_back:
			ld hl, ntc_lr
			jp ntc_lstore

;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

;## kw_l_print ntc_ltoa ntc_printbuf
;kw_l_print, <long>  - print a Long
kw_l_print:
			pop hl
			ld de, ntc_numbuf
			ld ix, ntc_lpr_back
			jp ntc_ltoa
ntc_lpr_back:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_l_cstr ntc_ltoa
;kw_l_cstr, <dest>, <long>  - Long to text
kw_l_cstr:
			pop de
			pop hl
			ld ix, ntc_next
			jp ntc_ltoa

;## kw_l_str ntc_ltoa
;kw_l_str, <dest>, <long>  - Str$(Long): a space before 0 and positives
kw_l_str:
			pop de
			pop hl
			inc hl
			inc hl
			inc hl
			bit 7, (hl)
			dec hl
			dec hl
			dec hl
			jr nz, ntc_lst_go
			ld a, ' '
			ld (de), a
			inc de
ntc_lst_go:
			ld ix, ntc_next
			jp ntc_ltoa

;## kw_l_val ntc_ldata ntc_data
;kw_l_val, <src>, <destlong>  - Val() to a Long (decimal)
kw_l_val:
			pop hl
			pop de
			ld (ntc_ldst), de
ntc_lv_go:
			ld de, 0
			ld (ntc_la), de
			ld (ntc_la+2), de
ntc_lv_sp:
			ld a, (hl)
			cp ' '
			jr nz, ntc_lv_sg
			inc hl
			jr ntc_lv_sp
ntc_lv_sg:
			xor a
			ld (ntc_lsgn), a
			ld a, (hl)
			cp '-'
			jr nz, ntc_lv_dig
			ld a, 1
			ld (ntc_lsgn), a
			inc hl
ntc_lv_dig:
			ld a, (hl)
			sub '0'
			jr c, ntc_lv_done
			cp 10
			jr nc, ntc_lv_done
			ld (ntc_lcnt), a
			ld (ntc_aptr), hl
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld hl, (ntc_la)
			ld (ntc_lt), hl
			ld hl, (ntc_la+2)
			ld (ntc_lt+2), hl
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld de, ntc_lt
			ld hl, ntc_la
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			ld hl, ntc_la
			ld a, (ntc_lcnt)
			add a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			adc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			adc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			adc a, (hl)
			ld (hl), a
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_lv_dig
ntc_lv_done:
			ld a, (ntc_lsgn)
			or a
			jr z, ntc_lv_st
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lv_st:
			ld hl, ntc_la
			ld de, (ntc_ldst)
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_aget
;kw_l_aget, <arraybase>, <indexvar>, <dest>  - Long array element
kw_l_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, hl
			add hl, de
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_aset
;kw_l_aset, <arraybase>, <indexvar>, <src>  - set a Long array element
kw_l_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ldi
			ldi
			ldi
			ldi
			ret

;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode (0, 1: 40 columns, 2: 80)
ntc_sinit:		db 0			; 1 once the tilemap is set up
ntc_scols:		db 40			; columns
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 8			; the 8 half rows this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_zxvs:		db 0			; 1: this interrupt is a frame's first (line 0 passed: to ntc_isl_tick in C)
ntc_zxline:		dw 0			; the raster line the line interrupt is set to
ntc_zxsel:		db 0			; the NextReg selected (#243B) by code interrupts can get into: the
								; handler selects it again after its own (store it, then select)
ntc_zxl2:		db 0			; 1 = Layer 2 is on (Graphics); Mode turns it off
ZXN_MAP			equ #E000		; the tilemap (bank 5 + #2000: NextReg #6E = #20)
ZXN_TILES		equ #EC00		; its characters (bank 5 + #2C00: NextReg #6F = #2C)
ZXN_ROWS		equ 32
ZXN_PAPER		equ #02			; RRRGGGBB: blue
ZXN_INK			equ #FC			; yellow

;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			cp 32
			jr c, ntc_pc_bad
			cp 127
			jr c, ntc_zx_put
ntc_pc_bad:
			ld a, '?'
			jr ntc_zx_put

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = an 8 byte glyph in ntc_font (ZOSCII text): that
; character at the cursor, the cursor on (a glyph not in ntc_font: ?)
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld hl, -ntc_font
			add hl, de				; HL = the glyph's offset: 0 .. 95 * 8 - 1
			ld a, h
			cp (95 * 8) / 256
			jr c, ntc_pg_in
			jr nz, ntc_pc_bad
			ld a, l
			cp (95 * 8) & 255
			jr nc, ntc_pc_bad
ntc_pg_in:
			srl h
			rr l
			srl h
			rr l
			srl h
			rr l
			ld a, l
			add a, 32
			; fall into ntc_zx_put

; A = a character code: into the tilemap at the cursor (its tile), the cursor on
ntc_zx_put:
			ld c, a
			ld a, (ntc_cury)		; HL = ZXN_MAP + row * columns + column
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; row * 40
			ld a, (ntc_scols)
			cp 80
			jr nz, $+3
			add hl, hl				; row * 80
			ld a, (ntc_curx)
			ld e, a
			ld d, ZXN_MAP / 256		; (ZXN_MAP's low byte is 0)
			add hl, de
			ld (hl), c
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp ZXN_ROWS
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_mode - A = mode: 0, 1 = 40 x 32, 2 (3) = 80 x 32. The first time the
; tilemap is set up (font, palette, its registers); then its width, clear screen
; ------------------------------------------------------------
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld (ntc_smode), a
			ld a, (ntc_sinit)
			or a
			jp nz, ntc_md_set
			inc a
			ld (ntc_sinit), a
			ld hl, ntc_zxfont		; the font to ntc_font (ZOSCII's glyphs point there)
			ld de, ntc_font
			ld bc, 95 * 8
			ldir
			ld hl, ZXN_TILES		; the tiles: 0-31 and 127-255 blank, 32-126 the font
			ld de, ZXN_TILES + 1
			ld bc, 256 * 8 - 1
			ld (hl), 0
			ldir
			ld hl, ntc_zxfont
			ld de, ZXN_TILES + 32 * 8
			ld bc, 95 * 8
			ldir
			ld bc, #243B
			ld a, #43
			out (c), a
			inc b
			ld a, #30
			out (c), a
			dec b					; palette: the tilemap's first, index 0 paper, 1 ink
			ld bc, #243B
			ld a, #40
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b
			ld a, #41
			out (c), a
			inc b
			ld a, ZXN_PAPER
			out (c), a
			ld a, ZXN_INK
			out (c), a				; (the index moves on by itself)
			ld bc, #243B
			ld a, #6C
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b					; every tile's attribute: palette offset 0
			ld bc, #243B
			ld a, #6E
			out (c), a
			inc b
			ld a, #20
			out (c), a
			dec b					; the map at bank 5 + #2000
			ld bc, #243B
			ld a, #6F
			out (c), a
			inc b
			ld a, #2C
			out (c), a
			dec b					; the tiles at bank 5 + #2C00
			ld bc, #243B
			ld bc, #243B
			ld a, #2F
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b					; no scroll
			ld bc, #243B
			ld a, #30
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b
			ld bc, #243B
			ld a, #31
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b
			ld bc, #243B
			ld a, #1C
			out (c), a
			inc b
			ld a, 8
			out (c), a
			dec b					; the tilemap's clip window: the whole of it
			ld a, #1B
			out (c), a
			inc b
			xor a
			out (c), a
			ld a, 159
			out (c), a
			xor a
			out (c), a
			dec a
			out (c), a
ntc_md_set:
			ld hl, ntc_md_regs		; the text screen alone: Layer 2 off (Graphics turns it on), the
			ld bc, #243B			; ULA on, the tilemap opaque, bank 5's first page at #C000
			ld e, 9
ntc_md_rg:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, ntc_md_rg
			xor a
			ld (ntc_zxl2), a
			ld a, (ntc_smode)
			cp 2
			ld a, 40
			ld e, #A9				; tilemap on, 40 x 32, no attributes, text mode, over the ULA
			jr nz, ntc_md_40
			ld a, 80
			ld e, #E9				; the same, 80 x 32
ntc_md_40:
			ld (ntc_scols), a
			ld bc, #243B
			ld a, #6B
			out (c), a
			inc b
			ld a, e
			out (c), a
			jp ntc_plat_cls

; NextReg, value: Layer 2 off, the ULA from bank 5, no Timex mode (#69); sprites off, the
; layers' order as at reset (#15); the ULA on, no ULA+ (#68); the tilemap's index 15
; transparent - its paper (0) not (#4C); page 10 at #C000 (#56: Graphics draws there); the
; tilemap's paper its colour again (Graphics makes it see-through)
ntc_md_regs:	db #69, 0, #15, 0, #68, 0, #4C, #0F, #56, 10, #57, 11, #43, #30, #40, 0, #41, ZXN_PAPER

; the font: font8x8_basic by Daniel Hepper (public domain) - chars 32-126, 8 bytes each,
; bit 7 the leftmost pixel
ntc_zxfont:
			db #00, #00, #00, #00, #00, #00, #00, #00	; 32
			db #18, #3C, #3C, #18, #18, #00, #18, #00	; 33 !
			db #6C, #6C, #00, #00, #00, #00, #00, #00	; 34 "
			db #6C, #6C, #FE, #6C, #FE, #6C, #6C, #00	; 35 #
			db #30, #7C, #C0, #78, #0C, #F8, #30, #00	; 36 $
			db #00, #C6, #CC, #18, #30, #66, #C6, #00	; 37 %
			db #38, #6C, #38, #76, #DC, #CC, #76, #00	; 38 &
			db #60, #60, #C0, #00, #00, #00, #00, #00	; 39 '
			db #18, #30, #60, #60, #60, #30, #18, #00	; 40 (
			db #60, #30, #18, #18, #18, #30, #60, #00	; 41 )
			db #00, #66, #3C, #FF, #3C, #66, #00, #00	; 42 *
			db #00, #30, #30, #FC, #30, #30, #00, #00	; 43 +
			db #00, #00, #00, #00, #00, #30, #30, #60	; 44 ,
			db #00, #00, #00, #FC, #00, #00, #00, #00	; 45 -
			db #00, #00, #00, #00, #00, #30, #30, #00	; 46 .
			db #06, #0C, #18, #30, #60, #C0, #80, #00	; 47 /
			db #7C, #C6, #CE, #DE, #F6, #E6, #7C, #00	; 48 0
			db #30, #70, #30, #30, #30, #30, #FC, #00	; 49 1
			db #78, #CC, #0C, #38, #60, #CC, #FC, #00	; 50 2
			db #78, #CC, #0C, #38, #0C, #CC, #78, #00	; 51 3
			db #1C, #3C, #6C, #CC, #FE, #0C, #1E, #00	; 52 4
			db #FC, #C0, #F8, #0C, #0C, #CC, #78, #00	; 53 5
			db #38, #60, #C0, #F8, #CC, #CC, #78, #00	; 54 6
			db #FC, #CC, #0C, #18, #30, #30, #30, #00	; 55 7
			db #78, #CC, #CC, #78, #CC, #CC, #78, #00	; 56 8
			db #78, #CC, #CC, #7C, #0C, #18, #70, #00	; 57 9
			db #00, #30, #30, #00, #00, #30, #30, #00	; 58 :
			db #00, #30, #30, #00, #00, #30, #30, #60	; 59 ;
			db #18, #30, #60, #C0, #60, #30, #18, #00	; 60 <
			db #00, #00, #FC, #00, #00, #FC, #00, #00	; 61 =
			db #60, #30, #18, #0C, #18, #30, #60, #00	; 62 >
			db #78, #CC, #0C, #18, #30, #00, #30, #00	; 63 ?
			db #7C, #C6, #DE, #DE, #DE, #C0, #78, #00	; 64 @
			db #30, #78, #CC, #CC, #FC, #CC, #CC, #00	; 65 A
			db #FC, #66, #66, #7C, #66, #66, #FC, #00	; 66 B
			db #3C, #66, #C0, #C0, #C0, #66, #3C, #00	; 67 C
			db #F8, #6C, #66, #66, #66, #6C, #F8, #00	; 68 D
			db #FE, #62, #68, #78, #68, #62, #FE, #00	; 69 E
			db #FE, #62, #68, #78, #68, #60, #F0, #00	; 70 F
			db #3C, #66, #C0, #C0, #CE, #66, #3E, #00	; 71 G
			db #CC, #CC, #CC, #FC, #CC, #CC, #CC, #00	; 72 H
			db #78, #30, #30, #30, #30, #30, #78, #00	; 73 I
			db #1E, #0C, #0C, #0C, #CC, #CC, #78, #00	; 74 J
			db #E6, #66, #6C, #78, #6C, #66, #E6, #00	; 75 K
			db #F0, #60, #60, #60, #62, #66, #FE, #00	; 76 L
			db #C6, #EE, #FE, #FE, #D6, #C6, #C6, #00	; 77 M
			db #C6, #E6, #F6, #DE, #CE, #C6, #C6, #00	; 78 N
			db #38, #6C, #C6, #C6, #C6, #6C, #38, #00	; 79 O
			db #FC, #66, #66, #7C, #60, #60, #F0, #00	; 80 P
			db #78, #CC, #CC, #CC, #DC, #78, #1C, #00	; 81 Q
			db #FC, #66, #66, #7C, #6C, #66, #E6, #00	; 82 R
			db #78, #CC, #E0, #70, #1C, #CC, #78, #00	; 83 S
			db #FC, #B4, #30, #30, #30, #30, #78, #00	; 84 T
			db #CC, #CC, #CC, #CC, #CC, #CC, #FC, #00	; 85 U
			db #CC, #CC, #CC, #CC, #CC, #78, #30, #00	; 86 V
			db #C6, #C6, #C6, #D6, #FE, #EE, #C6, #00	; 87 W
			db #C6, #C6, #6C, #38, #38, #6C, #C6, #00	; 88 X
			db #CC, #CC, #CC, #78, #30, #30, #78, #00	; 89 Y
			db #FE, #C6, #8C, #18, #32, #66, #FE, #00	; 90 Z
			db #78, #60, #60, #60, #60, #60, #78, #00	; 91 [
			db #C0, #60, #30, #18, #0C, #06, #02, #00	; 92 \
			db #78, #18, #18, #18, #18, #18, #78, #00	; 93 ]
			db #10, #38, #6C, #C6, #00, #00, #00, #00	; 94 ^
			db #00, #00, #00, #00, #00, #00, #00, #FF	; 95 _
			db #30, #30, #18, #00, #00, #00, #00, #00	; 96 `
			db #00, #00, #78, #0C, #7C, #CC, #76, #00	; 97 a
			db #E0, #60, #60, #7C, #66, #66, #DC, #00	; 98 b
			db #00, #00, #78, #CC, #C0, #CC, #78, #00	; 99 c
			db #1C, #0C, #0C, #7C, #CC, #CC, #76, #00	; 100 d
			db #00, #00, #78, #CC, #FC, #C0, #78, #00	; 101 e
			db #38, #6C, #60, #F0, #60, #60, #F0, #00	; 102 f
			db #00, #00, #76, #CC, #CC, #7C, #0C, #F8	; 103 g
			db #E0, #60, #6C, #76, #66, #66, #E6, #00	; 104 h
			db #30, #00, #70, #30, #30, #30, #78, #00	; 105 i
			db #0C, #00, #0C, #0C, #0C, #CC, #CC, #78	; 106 j
			db #E0, #60, #66, #6C, #78, #6C, #E6, #00	; 107 k
			db #70, #30, #30, #30, #30, #30, #78, #00	; 108 l
			db #00, #00, #CC, #FE, #FE, #D6, #C6, #00	; 109 m
			db #00, #00, #F8, #CC, #CC, #CC, #CC, #00	; 110 n
			db #00, #00, #78, #CC, #CC, #CC, #78, #00	; 111 o
			db #00, #00, #DC, #66, #66, #7C, #60, #F0	; 112 p
			db #00, #00, #76, #CC, #CC, #7C, #0C, #1E	; 113 q
			db #00, #00, #DC, #76, #66, #60, #F0, #00	; 114 r
			db #00, #00, #7C, #C0, #78, #0C, #F8, #00	; 115 s
			db #10, #30, #7C, #30, #30, #34, #18, #00	; 116 t
			db #00, #00, #CC, #CC, #CC, #CC, #76, #00	; 117 u
			db #00, #00, #CC, #CC, #CC, #78, #30, #00	; 118 v
			db #00, #00, #C6, #D6, #FE, #FE, #6C, #00	; 119 w
			db #00, #00, #C6, #6C, #38, #6C, #C6, #00	; 120 x
			db #00, #00, #CC, #CC, #CC, #7C, #0C, #F8	; 121 y
			db #00, #00, #FC, #98, #30, #64, #FC, #00	; 122 z
			db #1C, #30, #30, #E0, #30, #30, #1C, #00	; 123 {
			db #18, #18, #18, #00, #18, #18, #18, #00	; 124 |
			db #E0, #30, #30, #1C, #30, #30, #E0, #00	; 125 }
			db #76, #DC, #00, #00, #00, #00, #00, #00	; 126 ~

;## ntc_plat_scroll ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-31 up one, clear row 31
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, ZXN_ROWS - 1
			ld (ntc_cury), a
			ld a, (ntc_scols)
			ld c, a
			ld b, 0					; BC = a row
			ld hl, ZXN_MAP
			add hl, bc
			ld de, ZXN_MAP
			cp 80
			ld bc, (ZXN_ROWS - 1) * 40
			jr nz, ntc_sc_40
			ld bc, (ZXN_ROWS - 1) * 80
ntc_sc_40:
			ldir					; DE = the last row
			ld h, d
			ld l, e
			ld (hl), ' '
			inc de
			ld c, a
			dec c
			ld b, 0
			ldir
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - the whole tilemap spaces, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ZXN_MAP
			ld de, ZXN_MAP + 1
			ld bc, ZXN_ROWS * 80 - 1
			ld (hl), ' '
			ldir
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_key ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scankey - A = ASCII of a key pressed since the last scan,
; 0 if none
; ------------------------------------------------------------
ntc_plat_scankey:
			ld hl, ntc_kcur
			ld b, #FE				; half row 0 (address line A8 low) ... 7 (A15)
ntc_ks_line:
			ld c, #FE
			in a, (c)
			or #E0					; (bits 5-7: no keys)
			ld (hl), a
			inc hl
			rlc b
			jr c, ntc_ks_line		; (B's 0 bit moves up: done after A15)
			ld a, #FF
			ld (ntc_kidx), a
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld iy, ntc_kign
			ld bc, #0800			; B = 8 half rows, C = key index (half row * 8 + bit)
ntc_ks_find:
			ld a, (ntc_kidx)
			inc a
			jr nz, ntc_ks_next
			ld a, (hl)
			cpl
			ex de, hl
			and (hl)				; pressed now, released last scan
			ex de, hl
			and (iy+0)				; not Caps Shift / Symbol Shift
			jr z, ntc_ks_next
ntc_ks_bit:
			rrca
			jr c, ntc_ks_got
			inc c
			jr ntc_ks_bit
ntc_ks_got:
			ld a, c
			ld (ntc_kidx), a
ntc_ks_next:
			ld a, c
			and #F8
			add a, 8
			ld c, a
			inc hl
			inc de
			inc iy
			djnz ntc_ks_find
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld bc, 8
			ldir
			ld a, (ntc_kidx)
			cp #FF
			jr z, ntc_ks_none
			ld e, a
			ld d, 0
			ld hl, ntc_keymapy		; Symbol Shift (half row 7 bit 1) first
			ld a, (ntc_kcur + 7)
			bit 1, a
			jr z, ntc_ks_map
			ld hl, ntc_keymapc		; then Caps Shift (half row 0 bit 0)
			ld a, (ntc_kcur)
			bit 0, a
			jr z, ntc_ks_map
			ld hl, ntc_keymap
ntc_ks_map:
			add hl, de
			ld a, (hl)
			jp (ix)
ntc_ks_none:
			xor a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_getkey - wait for a key press, A = ASCII
; ------------------------------------------------------------
ntc_plat_getkey:
			ld (ntc_klink), ix
ntc_gk_scan:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr nz, ntc_gk_done
			ld a, (ntc_nmode)		; normal mode: interrupts in while waiting
			or a
			jr z, ntc_gk_wait
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_gk_wait:
			ld bc, 7000				; about 6ms between scans at 28MHz (debounce)
ntc_gk_delay:
			dec bc
			ld a, b
			or c
			jr nz, ntc_gk_delay
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_gk_scan
			ld sp, (ntc_ip)
			jr ntc_gk_scan
ntc_gk_done:
			ld ix, (ntc_klink)
			jp (ix)

; keys that never count as a press on their own (Caps Shift, Symbol Shift)
ntc_kign:		db #FE, #FF, #FF, #FF, #FF, #FF, #FF, #FD

; half row 0-7, bit 0-4 -> ASCII (0 = nothing); 8 a half row, 5-7 unused
; 0 Caps Z X C V   1 A S D F G   2 Q W E R T   3 1 2 3 4 5
; 4 0 9 8 7 6      5 P O I U Y  6 Enter L K J H   7 Space Symbol M N B
ntc_keymap:
			db 0, "z", "x", "c", "v", 0, 0, 0
			db "a", "s", "d", "f", "g", 0, 0, 0
			db "q", "w", "e", "r", "t", 0, 0, 0
			db "1", "2", "3", "4", "5", 0, 0, 0
			db "0", "9", "8", "7", "6", 0, 0, 0
			db "p", "o", "i", "u", "y", 0, 0, 0
			db 13, "l", "k", "j", "h", 0, 0, 0
			db " ", 0, "m", "n", "b", 0, 0, 0
ntc_keymapc:								; Caps Shift: capitals; + 0 DEL, + Space Break
			db 0, "Z", "X", "C", "V", 0, 0, 0
			db "A", "S", "D", "F", "G", 0, 0, 0
			db "Q", "W", "E", "R", "T", 0, 0, 0
			db 0, 0, 0, 0, 0, 0, 0, 0			; (Edit, Caps Lock, True / Inverse Video, cursor left)
			db 127, 0, 0, 0, 0, 0, 0, 0			; (Graphics, cursor right / up / down)
			db "P", "O", "I", "U", "Y", 0, 0, 0
			db 13, "L", "K", "J", "H", 0, 0, 0
			db 27, 0, "M", "N", "B", 0, 0, 0
ntc_keymapy:								; Symbol Shift: the symbols on the keys (+ the 128's ~ | \ { } [ ])
			db 0, ":", 0, "?", "/", 0, 0, 0		; (X: pound)
			db "~", "|", 92, "{", "}", 0, 0, 0
			db 0, 0, 0, "<", ">", 0, 0, 0		; (Q, W, E: <= <> >=)
			db "!", "@", "#", "$", "%", 0, 0, 0
			db "_", ")", "(", 39, "&", 0, 0, 0
			db 34, ";", 0, "]", "[", 0, 0, 0		; (I: copyright)
			db 13, "=", "+", "-", "^", 0, 0, 0
			db " ", 0, ".", ",", "*", 0, 0, 0

;## ntc_plat_irq ntc_plat_data ntc_data ntc_plat_irqh @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1: the stub set it) and
; start the line interrupt at raster line 0, the ULA's frame interrupt off
; (NextReg #22: bit 2 the ULA's off, bit 1 the line interrupt on, bit 0 the
; line's bit 8; #23 its bits 0-7). The handler moves it on 52 lines each time
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld hl, 0
			ld (ntc_zxline), hl
			ld bc, #243B
			ld a, #23
			out (c), a
			inc b
			xor a
			out (c), a
			dec b
			ld a, #22
			out (c), a
			inc b
			ld a, 6
			out (c), a
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

;## ntc_plat_irqh ntc_plat_data ntc_data @shared
; the handler: runs on the real stack, between keywords. The line interrupt, every 52 raster
; lines - 6 a frame of 312 lines, 300 a second, as the CPC's: counts the ticks and sets the
; next one. The Next's INT is a pulse (32 T at 3.5MHz), not held: a program with interrupts
; off while the line passes (a long stretch between two Frame waits, say) misses that one.
; So the next line is not simply this one + 52: the raster is read (#1E, #1F) and every 52
; line step from the line this interrupt was set for up to the raster now counts as a tick
; (the ones missed included: the clock keeps 300 a second), and the next interrupt is set at
; the step after - never at a line the raster has passed, which would leave the chain dead
; until it came round, or for ever if the program is always off at that line. The step at
; line 0 is a frame's first (ntc_zxvs 1 for the interrupt classes' counting: it is counted
; even when it was missed). AF goes to AF', HL to RAM, the other registers are kept.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			push bc
			push de
			ld bc, #243B
ntc_irq_rd:						; DE = the raster line now (#1E bit 8, #1F: read again until bit 8 holds)
			ld a, #1E
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_irq_rd
			and 1
			ld d, a
			ld hl, (ntc_zxline)		; the line this interrupt was set for
			ld a, h
			or l
			ld a, 0
			jr nz, ntc_irq_nf
			inc a
ntc_irq_nf:
			ld (ntc_zxvs), a		; 1: line 0, a frame's first (so far: a wrap below sets it too)
			ex de, hl				; HL = now, DE = set for
			or a
			sbc hl, de				; HL = now - set for
			jr nc, ntc_irq_fw
			ld bc, 16				; a little before it (the pulse comes as the line before ends): 0
			add hl, bc
			jr c, ntc_irq_z
			ld bc, 312 - 16			; else the raster wrapped: + 312
			add hl, bc
			jr ntc_irq_fw
ntc_irq_z:
			ld hl, 0
ntc_irq_fw:
			ld c, 1					; C = the ticks: 1 + (now - set for) / 52
			ld b, 0					; (BC = 52 * the ticks past the first, the step to the next line)
ntc_irq_dv:
			ld a, l
			sub 52
			ld l, a
			ld a, h
			sbc a, 0
			ld h, a
			jr c, ntc_irq_dd
			inc c
			ld a, c
			cp 7					; (6 at most: a frame)
			jr c, ntc_irq_dv
			dec c
ntc_irq_dd:
			ld a, c
			ld (ntc_irqn), a
			ld hl, (ntc_ticks)
			ld b, 0
			add hl, bc
			ld (ntc_ticks), hl
			ld hl, 0				; the next line: set for + 52 * the ticks (mod 312)
			ld bc, 52
			ld a, (ntc_irqn)
ntc_irq_st:
			add hl, bc
			dec a
			jr nz, ntc_irq_st
			add hl, de
			ld bc, -312
			add hl, bc
			jr c, ntc_irq_wrp		; past the last line (312 and on): wrapped - line 0 was passed
			sbc hl, bc				; (carry clear: back to the line)
			jr ntc_irq_wr
ntc_irq_wrp:
			ld a, (ntc_irqn)		; the wrap: the step at line 0 was one of these ticks, unless it is
			dec a					; the next one (the only tick was the one set for: HL = 0 now)
			jr nz, ntc_irq_wv
			ld a, h
			or l
			jr z, ntc_irq_wr
ntc_irq_wv:
			ld a, 1
			ld (ntc_zxvs), a
ntc_irq_wr:
			ld (ntc_zxline), hl
			ld bc, #243B
			ld a, #23
			out (c), a
			inc b
			out (c), l
			dec b
			ld a, #22
			out (c), a
			inc b
			ld a, h
			or 6					; the ULA's interrupt off, the line interrupt on
			out (c), a
			dec b
			ld a, (ntc_zxsel)		; the NextReg the code it came in on had selected
			out (c), a
			pop de
			pop bc
			ld a, (ntc_hookon)	; an Interrupt hook: run it at the next safe point
			or a
			jr z, ntc_irq_nohook
			ld (ntc_hookpend), a
ntc_irq_nohook:
			ld hl, (ntc_irqv)		; interrupt classes (Option Class Interrupt): count them - once
			ld a, h					; a tick (the missed ones too: the frame's first among them last,
			or l					; so the classes see it in the same order as the ticks came)
			jr z, ntc_irq_nocl
			push bc
			ld a, (ntc_irqn)
			ld b, a
ntc_irq_cl:
			ld c, 0					; C = 1: a frame's first (ntc_isl_tick reads it on zxn)
			dec b
			jr nz, ntc_irq_cl1
			ld a, (ntc_zxvs)
			ld c, a
ntc_irq_cl1:
			inc b
			push bc
			push hl
			call ntc_irq_jp			; (the handler runs on the real stack)
			pop hl
			pop bc
			djnz ntc_irq_cl
			pop bc
ntc_irq_nocl:
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			ret
ntc_irq_jp:
			jp (hl)
ntc_irqn:		db 1			; the ticks this interrupt counted (1-6)

;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - the end: interrupts off, a soft reset (NextReg 2 bit 0) -
; back to NextZXOS (a NEX file has no caller to return to)
; ------------------------------------------------------------
ntc_plat_exit:
			di
			ld bc, #243B
			ld a, #02
			out (c), a
			inc b
			ld a, 1
			out (c), a
ntc_ex_wait:
			jr ntc_ex_wait

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #BE00 (the stack is above, to #C000). Called on the real stack
; (call / ret), only by the Memory class.
ntc_plat_memtop:
			ld hl, #BE00
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_arr		equ ntc_bss + 0		; 20 bytes
ntc_bss_size	equ 20
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			ASSERT ntc_free <= #BE00, "the program and its arrays must end below #BE00 (the stack is #BE00-#BFFF, the screen #C000-#FFFF)"
			MMU 3, 11			; page 11 (bank 5's second half) at #6000 to assemble the stub
			org #7E00
zxn_boot:
			di
			ld bc, #243B		; NextReg select (#253B: its value)
			ld a, 6			; Peripheral 2: the NMI buttons off (bit 3 Multiface M1, bit 4 DivMMC DRIVE)
			out (c), a
			inc b
			in a, (c)
			and %11100111
			out (c), a
			dec b
			ld a, 10			; Peripheral 5: DivMMC automatic paging off (bit 4)
			out (c), a
			inc b
			in a, (c)
			and %11101111
			out (c), a
			dec b
			xor a
			out (#E3), a		; DivMMC: its memory out
			ld a, 7			; CPU speed: 28MHz
			out (c), a
			inc b
			ld a, 3
			out (c), a
			dec b
			ld hl, zxn_mmu		; the slots but 3
			ld e, 7
zxn_bmmu:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, zxn_bmmu
			jp zxn_boot2 + #8000	; on in the copy at #E000-#FFFF (page 11 in slot 7)
zxn_boot2:
			ld a, #53			; slot 3: page 19
			out (c), a
			inc b
			ld a, 19
			out (c), a
			ld hl, #C9FB		; #0038: ei, ret until ntc_plat_irqon puts its jump there
			ld (#0038), hl
			im 1
			jp ntc_start
zxn_mmu:	db #50, 16, #51, 17, #52, 18, #54, 20, #55, 21, #56, 10, #57, 11
			SAVENEX OPEN "LONGTEST.NEX", zxn_boot, #BFFE
